let AC=null;function beep(ok){try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain();o.frequency.value=ok?1250:300;g.gain.value=.15;o.connect(g);g.connect(AC.destination);o.start();o.stop(AC.currentTime+(ok?.09:.3))}catch(e){}}

async function loadCat(){
 const key="poscat_"+ME.br;let c=null;try{c=JSON.parse(localStorage.getItem(key)||"null")}catch(e){}
 if(c)setCat(c.rows);
 const j=await api("/api/pos/cat");if(j.ok){setCat(j.rows);try{localStorage.setItem(key,JSON.stringify({at:j.at,rows:j.rows}))}catch(e){}}
}
function norm(s){return String(s).toLowerCase().replace(/[أإآ]/g,"ا").replace(/ة/g,"ه").replace(/ى/g,"ي").replace(/\s+/g," ").trim()}
function setCat(rows){CAT=rows.map(r=>({c:r[0],n:r[1],p:r[2],k:norm(r[1])}));BY=new Map(CAT.map(x=>[x.c,x]))}

function search(t){
 t=t.trim();if(!t)return[];
 if(/^\d+$/.test(t)){const ex=BY.get(t);const L=ex?[ex]:[];for(const x of CAT){if(L.length>=8)break;if(x!==ex&&x.c.startsWith(t))L.push(x)}return L}
 const w=norm(t).split(" ");const L=[];for(const x of CAT){if(w.every(a=>x.k.includes(a)||x.c.includes(a))){L.push(x);if(L.length>=8)break}}return L;
}
