 hits=search(t);sel=hits.length?0:-1;
 d.innerHTML=hits.length?hits.map((x,i)=>`<div data-i="${i}" class="${i===sel?"h":""}"><span>${esc(x.n)} <span class="c">${esc(x.c)}</span></span><b>${f2(x.p)}</b></div>`).join(""):`<div class="e">لا يوجد صنف بهذا الباركود أو الاسم</div>`;
 d.classList.add("show")}
