 const c=$("cart");
 if(!cart.length)c.innerHTML=`<div class="empty">امسح باركود أو اكتب اسم الصنف لبدء الفاتورة</div>`;
 else c.innerHTML=`<table><tr><th class="n">#</th><th>الصنف</th><th style="width:100px">السعر</th><th style="width:150px">الكمية</th><th style="width:110px">المجموع</th><th style="width:44px"></th></tr>`+
  cart.map((l,i)=>`<tr class="${l.c===lastCode?"last":""}"><td class="n">${i+1}</td><td>${esc(l.n)}<span class="code">${esc(l.c)}</span></td><td>${f2(l.p)}</td><td><span class="q"><button data-a="-" data-i="${i}">−</button><input data-i="${i}" value="${l.q}" inputmode="decimal"><button data-a="+" data-i="${i}">+</button></span></td><td><b>${f2(l.p*l.q)}</b></td><td><button class="del" data-a="x" data-i="${i}"><i class="ti ti-trash"></i></button></td></tr>`).join("")+`</table>`;
 const{t,n}=totals();$("total").textContent=f2(t);$("cnt").textContent=cart.length+" أصناف · "+(Math.round(n*1000)/1000)+" قطع";
 const v=ME&&ME.vat?r2(t*15/115):0;$("vat").textContent=f2(v);$("net").textContent=f2(t-v);
 mixCalc();
}
$("cart").addEventListener("click",e=>{const b=e.target.closest("button[data-a]");if(!b)return;const i=+b.dataset.i,L=cart[i];
 if(b.dataset.a==="+")L.q=r2(L.q+1);else if(b.dataset.a==="-"){L.q=r2(L.q-1);if(L.q<=0)cart.splice(i,1)}else cart.splice(i,1);render()});
$("cart").addEventListener("change",e=>{if(e.target.tagName!=="INPUT")return;const i=+e.target.dataset.i,v=+e.target.value;if(v>0)cart[i].q=Math.round(v*1000)/1000;else cart.splice(i,1);render()});
$("clrBtn").onclick=()=>{if(cart.length&&confirmClr()){cart=[];render()}};
function confirmClr(){if(confirmClr.t&&Date.now()-confirmClr.t<2500){confirmClr.t=0;return true}confirmClr.t=Date.now();toast("اضغط «تفريغ السلة» مرة ثانية للتأكيد");return false}

function setMode(m){mode=m;document.querySelectorAll(".pm").forEach(b=>b.classList.toggle("on",b.dataset.m===m));$("mixBox").style.display=m==="mix"?"block":"none";if(m==="mix"){$("cashIn").focus();$("cashIn").select()}mixCalc()}
document.querySelectorAll(".pm").forEach(b=>b.onclick=()=>setMode(b.dataset.m));
function mixCalc(){const t=totals().t,c=+$("cashIn").value||0;$("cardIn").value=f2(Math.max(0,t-c))}
$("cashIn").addEventListener("input",mixCalc);
$("cashIn").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();save()}});

// queue: an invoice is never lost — if the network drops it waits and is resent with the same id
function Q(){try{return JSON.parse(localStorage.getItem("posq")||"[]")}catch(e){return[]}}
function setQ(a){try{localStorage.setItem("posq",JSON.stringify(a))}catch(e){}pendShow()}
function pendShow(){const n=Q().length;$("pend").textContent=n?("فواتير بانتظار الإرسال: "+n):""}
async function flush(){const a=Q();if(!a.length)return;const keep=[];for(const s of a){try{const j=await api("/api/pos/sale",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(s)});if(!j.ok&&j.err!=="item"&&j.err!=="empty"&&j.err!=="pay")keep.push(s);else if(!j.ok)toast("فاتورة لم تُقبل: "+j.err,4000)}catch(e){keep.push(s)}}setQ(keep);netState(!keep.length);loadDay()}
function netState(ok){$("netDot").classList.toggle("off",!ok);$("netTxt").textContent=ok?"متصل بالدفتر · تُحفظ الفواتير لحظياً":"غير متصل · الفواتير محفوظة في الجهاز وتُرسل تلقائياً"}
setInterval(flush,5000);
let saving=false;
async function save(){
 if(saving)return;$("err").textContent="";if(!cart.length){$("err").textContent="السلة فارغة";return}
 const t=totals().t;let cash=mode==="cash"?t:mode==="card"?0:r2(+$("cashIn").value||0);
 if(mode==="mix"&&(cash<=0||cash>=t)){$("err").textContent="اكتب المبلغ النقدي (أقل من الإجمالي)";$("cashIn").focus();return}
 const s={cid:Date.now().toString(36)+Math.random().toString(36).slice(2,10),at:Date.now(),lines:cart.map(l=>[l.c,l.q]),mode,cash};
 const snap=cart.slice();saving=true;$("saveBtn").disabled=true;
 try{const j=await api("/api/pos/sale",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(s)});
  if(j.ok){done(snap,t,cash,j.no);netState(true)}else{$("err").textContent=j.err==="item"?("صنف غير معروف: "+j.code):"لم تُحفظ: "+j.err}}
 catch(e){setQ(Q().concat([s]));netState(false);done(snap,t,cash,null)}
 saving=false;$("saveBtn").disabled=false;
}
function done(snap,t,cash,no){LASTINV={no,lines:snap,total:t,cash,card:r2(t-cash),mode,at:new Date(),vat:ME.vat?r2(t*15/115):0};cart=[];$("cashIn").value="";setMode("cash");render();toast(no?("حُفظت الفاتورة رقم "+no+" · "+f2(t)):"حُفظت في الجهاز وستُرسل تلقائياً",2200);loadDay();$("q").focus()}
$("saveBtn").onclick=save;
document.addEventListener("keydown",e=>{if(e.key==="F2"){e.preventDefault();setMode("cash");save()}else if(e.key==="F3"){e.preventDefault();setMode("card");save()}else if(e.key==="F4"){e.preventDefault();setMode("mix")}});

$("prnBtn").onclick=()=>{const L=LASTINV;if(!L){toast("لا توجد فاتورة محفوظة في هذا الجهاز بعد");return}
 const d=L.at;$("rc").innerHTML=`<div style="text-align:center;font-weight:600;font-size:15px">أسواق طيبة</div><div style="text-align:center">${esc(ME.brName)}</div><div style="text-align:center">فاتورة رقم ${L.no||"—"} · ${d.getDate()}/${d.getMonth()+1}/${d.getFullYear()} ${d.toTimeString().slice(0,5)}</div><div style="text-align:center">الكاشير: ${esc(ME.name)}</div><hr><table style="width:100%">${L.lines.map(l=>`<tr><td>${esc(l.n)}<br>${l.q} × ${f2(l.p)}</td><td style="text-align:left">${f2(l.p*l.q)}</td></tr>`).join("")}</table><hr>${ME.vat?`<div>قبل الضريبة: ${f2(L.total-L.vat)}</div><div>الضريبة 15%: ${f2(L.vat)}</div>`:""}<div style="font-size:16px;font-weight:600">الإجمالي: ${f2(L.total)} ر.س</div><div>نقدي ${f2(L.cash)} · شبكة ${f2(L.card)}</div>`;window.print()};

// camera: live reading (BarcodeDetector where the browser has it, otherwise ZXing)
let stream=null,camOn=false,lastScan={c:"",t:0},zx=null;
async function camStart(){
 const v=$("vid");camOn=true;$("camWrap").classList.add("show");$("camBtn").classList.add("on");$("camBtn").querySelector("span").textContent="إيقاف الكاميرا";$("camMsg").textContent="وجّه الكاميرا على الباركود";
 let bd=null;if("BarcodeDetector" in window){try{const f=await BarcodeDetector.getSupportedFormats();if(f.includes("ean_13"))bd=new BarcodeDetector({formats:f})}catch(e){bd=null}}
 if(bd){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment",width:{ideal:1280}},audio:false})}catch(e){toast("لم يُسمح بالكاميرا",3000);camStop();return}
  v.srcObject=stream;await v.play();const tick=async()=>{if(!camOn)return;try{const r=await bd.detect(v);if(r[0])onScan(r[0].rawValue)}catch(e){}setTimeout(tick,120)};tick();return}
 if(!window.ZXing){$("camMsg").textContent="المتصفح لا يدعم القراءة بالكاميرا";return}
 zx=new ZXing.BrowserMultiFormatReader();
 try{await zx.decodeFromConstraints({video:{facingMode:"environment",width:{ideal:1280}}},v,(res)=>{if(res&&camOn)onScan(res.getText())})}catch(e){toast("لم يُسمح بالكاميرا",3000);camStop()}
}
function camStop(){camOn=false;try{zx&&zx.reset()}catch(e){}zx=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$("camWrap").classList.remove("show");$("camBtn").classList.remove("on");$("camBtn").querySelector("span").textContent="قراءة بالكاميرا"}
function onScan(code){code=String(code).trim();const now=Date.now();if(code===lastScan.c&&now-lastScan.t<1500)return;lastScan={c:code,t:now};const x=BY.get(code);if(x){add(x);$("camMsg").textContent="أُضيف: "+x.n}else{beep(false);$("camMsg").textContent="غير موجود: "+code}}
$("camBtn").onclick=()=>camOn?camStop():camStart();

// today's invoices (cashier: his own; owner: all, with live totals per branch)
async function loadDay(){try{const j=await api("/api/pos/day");if(!j.ok)return;
 $("last").innerHTML=j.inv.length?j.inv.slice(0,ME.owner?12:6).map(d=>`<div class="inv"><span>${d.no} · ${d.mode==="cash"?"نقدي":d.mode==="card"?"شبكة":"نقدي + شبكة"}${ME.owner?" · "+esc(d.u)+" · "+(BRN[d.br]||""):""} · ${d.t.slice(0,5)}</span><span>${f2(d.total)}</span></div>`).join(""):`<div class="inv">لا توجد فواتير اليوم</div>`;
 if(ME.owner){$("ownDay").textContent=j.day.split("-").reverse().join("/");$("sumg").innerHTML=Object.keys(BRN).map(k=>{const s=j.sum[k]||{n:0,total:0,cash:0,card:0};return`<div class="sb"><div class="k">${BRN[k]}</div><div class="v">${f2(s.total)}</div><div class="s">${s.n} فاتورة · نقدي ${f2(s.cash)} · شبكة ${f2(s.card)}</div></div>`}).join("")}
}catch(e){}}
async function loadBr(){const j=await api("/api/pos/branches");if(!j.ok)return;const us=[{email:j.owner,name:"صاحب المحل"}].concat(j.users.filter(u=>u.email!==j.owner));
 $("brList").innerHTML=us.map(u=>{const b=j.map[u.email]||"shop";return`<div class="ur"><span>${esc(u.name||u.email)}<span class="code">${esc(u.email)}</span></span><span class="bb"><button data-e="${esc(u.email)}" data-b="shop" class="${b==="shop"?"on":""}">المبيعات</button><button data-e="${esc(u.email)}" data-b="del" class="${b==="del"?"on":""}">التوصيل</button></span></div>`}).join("")}
$("brList").addEventListener("click",async e=>{const b=e.target.closest("button[data-b]");if(!b)return;const j=await api("/api/pos/branches",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:b.dataset.e,br:b.dataset.b})});if(j.ok){toast("تم");loadBr();if(b.dataset.e===ME.email)location.reload()}});

(async()=>{ME=await api("/api/pos/me");if(!ME.ok)return;
 $("brName").textContent=ME.brName;$("uName").textContent=ME.name;$("vatRows").style.display=ME.vat?"block":"none";
 if(ME.owner){$("ownCard").style.display="block";$("brCard").style.display="block";$("lastTtl").textContent="آخر الفواتير";loadBr()}
 render();pendShow();await loadCat();loadDay();setInterval(loadDay,ME.owner?4000:20000);flush()})();
</script>
</body></html>
